        jnr_add_supplies.is_food_item as is_food_item,
        jnr_add_supplies.is_drink_item as is_drink_item,
        case when (jnr_add_supplies.customer_name is null) then 'Unknown' else jnr_add_supplies.customer_name end as customer_name,
        case when (jnr_add_supplies.location_name is null) then 'Unknown' else jnr_add_supplies.location_name end as location_name,
        case when (jnr_add_supplies.region is null) then 'Unknown' else jnr_add_supplies.region end as region,
        jnr_add_supplies.product_price as item_revenue,
        (case when (jnr_add_supplies.supply_cost_per_product is null) then 0 else jnr_add_supplies.supply_cost_per_product end) as item_cogs,
        jnr_add_supplies.product_price - (case when (jnr_add_supplies.supply_cost_per_product is null) then 0 else jnr_add_supplies.supply_cost_per_product end) as item_gross_profit,
        (case when jnr_add_supplies.product_price = 0 then 0 else (jnr_add_supplies.product_price - (case when (jnr_add_supplies.supply_cost_per_product is null) then 0 else jnr_add_supplies.supply_cost_per_product end)) / jnr_add_supplies.product_price end) as item_gross_margin_pct,
        jnr_add_supplies.product_price * (case when (jnr_add_supplies.tax_rate is null) then 0 else jnr_add_supplies.tax_rate end) as item_tax_estimate,
        jnr_add_supplies.product_price + jnr_add_supplies.product_price * (case when (jnr_add_supplies.tax_rate is null) then 0 else jnr_add_supplies.tax_rate end) as item_total_estimate,
        (case when (jnr_add_supplies.has_perishable_supply is null) then 0 else jnr_add_supplies.has_perishable_supply end) as has_perishable_supply
    from jnr_add_supplies

